export interface Receipt { id: number; tenant: string; key: string; cents: number }
export class Ledger {
  readonly entries: Receipt[] = [];
  // Idempotency records scoped by tenant and key.
  private readonly byScope = new Map<string, Receipt>();
  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    // No await before the check-and-insert below, so concurrent calls are serialized.
    const scope = JSON.stringify([tenant, key]);
    const existing = this.byScope.get(scope);
    if (existing) {
      if (existing.cents !== cents) throw new Error('key conflict');
      return existing;
    }
    const receipt: Receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.byScope.set(scope, receipt);
    this.entries.push(receipt);
    return receipt;
  }
}
EOF
cat > src/service.ts <<'EOF'
import { Ledger, Receipt } from './ledger';
import { Transient, Transport } from './transport';
export class PaymentService {
  constructor(private readonly ledger: Ledger, private readonly transport: Transport) {}
  async pay(tenant: string, key: string, cents: number, attempts = 3): Promise<Receipt> {
    if (
      typeof tenant !== 'string' || tenant.length === 0 ||
      typeof key !== 'string' || key.length === 0 ||
      !Number.isInteger(cents) || cents <= 0 ||
      !Number.isInteger(attempts) || attempts < 1 || attempts > 5
    ) throw new Error('invalid payment');
    // Debit exactly once; only the acknowledgement is retried with the same receipt.
    const receipt = await this.ledger.apply(tenant, key, cents);
    for (let n = 0; n < attempts; n++) {
      try {
        await this.transport.acknowledge(receipt);
        return receipt;
      } catch (error) {
        if (!(error instanceof Transient) || n === attempts - 1) throw error;
      }
    }
    throw new Error('invalid payment');
  }
}
EOF
cat > checks/retry.cjs <<'EOF'
const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  // Transient ack after commit: retried with same receipt, one debit.
  {
    const ledger = new Ledger(); let calls = 0; const seen = [];
    const t = { acknowledge: async r => { seen.push(r); if (++calls < 3) throw new Transient('x'); } };
    const s = new PaymentService(ledger, t);
    const r = await s.pay('a', 'k', 5);
    assert.equal(ledger.entries.length, 1); assert.equal(calls, 3);
    assert.ok(seen.every(x => x === r));
  }
  // Exhaustion rethrows the final Transient; attempts respected.
  {
    const ledger = new Ledger(); let calls = 0; const err = new Transient('final');
    const s = new PaymentService(ledger, { acknowledge: async () => { calls++; throw err; } });
    await assert.rejects(s.pay('a', 'k', 5, 2), e => e === err);
    assert.equal(calls, 2); assert.equal(ledger.entries.length, 1);
  }
  // Non-transient errors are not retried.
  {
    let calls = 0; const boom = new Error('boom');
    const s = new PaymentService(new Ledger(), { acknowledge: async () => { calls++; throw boom; } });
    await assert.rejects(s.pay('a', 'k', 5), e => e === boom); assert.equal(calls, 1);
  }
  // Same tenant/key + same amount returns the original receipt, concurrently too.
  {
    const ledger = new Ledger(); const s = new PaymentService(ledger, { acknowledge: async () => {} });
    const [x, y] = await Promise.all([s.pay('a', 'k', 5), s.pay('a', 'k', 5)]);
    assert.deepEqual(x, y); assert.equal(ledger.entries.length, 1);
    // Different tenant with same key is a separate scope.
    const z = await s.pay('b', 'k', 5); assert.equal(ledger.entries.length, 2); assert.equal(z.tenant, 'b');
  }
  // Key conflict: different amount throws without debit.
  {
    const ledger = new Ledger(); const s = new PaymentService(ledger, { acknowledge: async () => {} });
    await s.pay('a', 'k', 5);
    await assert.rejects(s.pay('a', 'k', 6), /key conflict/);
    assert.equal(ledger.entries.length, 1);
  }
  // Invalid input performs no ledger or transport action.
  {
    let touched = 0;
    const ledger = new Ledger(); const origApply = ledger.apply.bind(ledger);
    ledger.apply = async (...a) => { touched++; return origApply(...a); };
    const s = new PaymentService(ledger, { acknowledge: async () => { touched++; } });
    for (const args of [['', 'k', 1], ['a', '', 1], ['a', 'k', 0], ['a', 'k', 1.5], ['a', 'k', 1, 0], ['a', 'k', 1, 6], ['a', 'k', 1, 2.5]]) {
      await assert.rejects(s.pay(...args), /invalid payment/);
    }
    assert.equal(touched, 0);
  }
}
module.exports = main();
EOF
